param([switch]$Baseline)
$ErrorActionPreference='Stop';$repo=[IO.Path]::GetFullPath("$PSScriptRoot/../..")
$out="$repo/build-extractors/runtime-test/hodir-landing-source/$(Get-Date -Format yyyyMMdd-HHmmss-fff)";New-Item -ItemType Directory -Force $out|Out-Null
function Block([string]$s,[string]$key){$a=$s.IndexOf($key);if($a -lt 0){throw "Missing $key"};$b=$s.IndexOf('{',$a)+1;$depth=1;while($depth){if($s[$b] -eq '{'){++$depth};if($s[$b] -eq '}'){--$depth};++$b};$s.Substring($a,$b-$a)}
function Section([string]$s,[string]$a,[string]$b){$i=$s.IndexOf($a);$j=$s.IndexOf($b,$i+1);if($i -lt 0 -or $j -le $i){throw "Missing native boundary $a"};$s.Substring($i,$j-$i)}
& "$PSScriptRoot/Invoke-WithRuntimeDiagnostics.ps1" -EvidenceDirectory "$out/evidence" -RuntimeDirectories @($out) -Test {
 $s=Get-Content "$repo/src/server/game/Conditions/ConditionMgr.cpp" -Raw
 foreach($row in @(@('ScenarioCondition','        case CONDITION_SCENARION_STEP:','        case CONDITION_REALM_ACHIEVEMENT:'),@('ElseGroups','bool ConditionMgr::IsObjectMeetToConditionList(','bool ConditionMgr::IsObjectMeetToConditions(WorldObject* object,'),@('EventConditions','bool ConditionMgr::IsObjectMeetingSmartEventConditions(','bool Condition::isLoaded() const'),@('Lookup','ConditionList ConditionMgr::GetConditionsForSmartEvent(','ConditionList ConditionMgr::GetConditionsForNpcVendorEvent('))){[IO.File]::WriteAllText("$out/$($row[0]).inc",(Section $s $row[1] $row[2]))}
 $s=Get-Content "$repo/src/server/game/AI/SmartScripts/SmartScript.cpp" -Raw
 foreach($row in @(@('CreditPlayer','Player* GetScriptCreditPlayer('),@('Dispatch','void SmartScript::ProcessEventsFor('),@('FindLink','SmartScriptHolder SmartScript::FindLinkedEvent('))){[IO.File]::WriteAllText("$out/$($row[0]).inc",(Block $s $row[1]))}
 foreach($row in @(@('InvokerTarget','        case SMART_TARGET_NONE:','        case SMART_TARGET_ACTION_INVOKER_VEHICLE:'),@('EventPrefix','    if (!e.active && e.GetEventType() != SMART_EVENT_LINK)','    switch (e.GetEventType())'),@('TriggerEvent','        case SMART_EVENT_EVENTOBJECT_ONTRIGGER:','        case SMART_EVENT_ON_APPLY_OR_REMOVE_AURA:'),@('ActionStart','    e.runOnce = true;','    if (Unit* tempInvoker = GetLastInvoker())'),@('CriteriaAction','        case SMART_ACTION_UPDATE_ACHIEVEMENT_CRITERIA:','        case SMART_ACTION_SUMMON_CONVERSATION:'),@('RemoveAction','        case SMART_ACTION_REMOVEAURASFROMSPELL:','        case SMART_ACTION_FOLLOW:'),@('LinkTail','    if (e.link && e.link != e.event_id)','void SmartScript::InstallTemplate('))){[IO.File]::WriteAllText("$out/$($row[0]).inc",(Section $s $row[1] $row[2]))}
 [IO.File]::WriteAllText("$out/rows.tsv",$(if($Baseline){'10 89'}else{'13 61'}))
 $vs=& "${env:ProgramFiles(x86)}/Microsoft Visual Studio/Installer/vswhere.exe" -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath
 [IO.File]::WriteAllText("$out/run.cmd","@echo off`r`ncall `"$vs/VC/Auxiliary/Build/vcvars64.bat`" >nul`r`ncl /nologo /EHsc /std:c++17 /W4 /fsanitize=address /Zi /Fd`"$out/compiler.pdb`" /I`"$out`" `"$PSScriptRoot/HodirLandingTest.cpp`" /Fe`"$out/test.exe`" /Fo`"$out/test.obj`"`r`nif errorlevel 1 exit /b 1`r`n`"$out/test.exe`" `"$out/rows.tsv`"`r`nexit /b %errorlevel%`r`n")
 & "$out/run.cmd" *> "$out/source.log";if($LASTEXITCODE){Get-Content "$out/source.log" -Tail 5;throw 'Hodir source ASAN failed'};Get-Content "$out/source.log" -Tail 2
}
